{"code": "const script = String.raw`
import pickle
D=pickle.load(open('tmp/s1942_small.pkl','rb'))
A=D['A1']; B=D['B1']
def monomial_term(exp, coef):
    a,b,c=exp
    factors=[]
    if a: factors.append(f"W.b\u2082 ^ {a}" if a>1 else "W.b\u2082")
    if b: factors.append(f"W.b\u2084 ^ {b}" if b>1 else "W.b\u2084")
    if c: factors.append(f"W.b\u2086 ^ {c}" if c>1 else "W.b\u2086")
    s=" * ".join(factors) if factors else "1"
    if coef==1: return s
    if coef==-1: return "-" + s
    return f"({coef} : F) * " + s if not factors else f"({coef} : F) * " + s
def poly_expr(coeffs):
    # coeffs: list of dict exponent->coef for X^0..X^d
    terms=[]
    for i,p in enumerate(coeffs):
        if not p: continue
        # sort terms for readability: by a,b,c
        subterms=[]
        for exp in sorted(p.keys()):
            coef=p[exp]
            subterms.append(monomial_term(exp,coef))
        inner=" + ".join(subterms).replace("+ -","- ")
        if i==0:
            terms.append(f"C ({inner})")
        else:
            xpart="X" if i==1 else f"X ^ {i}"
            terms.append(f"C ({inner}) * {xpart}")
    return " +\n    ".join(terms)
def def_poly(name, coeffs):
    lines=[f"def {name} (W : WeierstrassCurve F) : F[X] :="]
    lines.append("  " + poly_expr(coeffs))
    return "\n".join(lines)
code = "import tmp.sheaf.xif.paper.S1933PrePsiSeparableActual\n\n"
code += "noncomputable section\n\n"
code += "namespace LeanFormal.IUT.XiFPaper.S1942PrePsiFiveProbe\n\n"
code += "open Polynomial WeierstrassCurve\n\n"
code += "variable {F : Type*} [Field F] [CharZero F]\n\n"
code += def_poly("S1942A", A) + "\n\n"
code += def_poly("S1942B", B) + "\n\n"
code += "end LeanFormal.IUT.XiFPaper.S1942PrePsiFiveProbe\n"
open('tmp/_S1942_probe_defs.lean','w',encoding='utf-8').write(code)
print("written", len(code), "chars")
print(code[:2000])
`;
await tools.write({ file_path: "D:\\lean\\tmp\\s1942_gen_lean.py", content: script });
const r = await tools.pwsh({ description: "Generate Lean definitions for A1 and B1", command: "python -u tmp\\s1942_gen_lean.py", timeoutMs: 60000 });
console.log(r.stdout.text); console.log(r.stderr.text);
